<?php
/** Proof — reverse and void (spec "Proof", 4): the reversal swapped, dated, posted, linked both ways; a reversal of a reversed one; Bea on Carl's → 403; Carl may; the closed period → today; a document-born entry refused; void a draft; void a posted one refused. */
require __DIR__ . '/lib.php';
$owner = as_member(1); $bea = as_member(27); $carl = as_member(28);
ensure_year($owner);
echo "1. Bea reverses her own\n";
[$c, $b, $id] = draft($bea, '2026-05-05', [['account' => '6100', 'debit' => '240', 'description' => 'SMOKE wrong month'], ['account' => '1010', 'credit' => '240']], 'SMOKE to reverse');
act($bea, '/journal/post.php', ['entry' => $id]);
$number = (string) one('SELECT number FROM journal_entries WHERE id = :i', ['i' => $id]);
[$c, $b] = act($bea, '/journal/reverse.php', ['entry' => $id, 'reason' => '']);
ok($c === 422 && msg($b) === 'A reversal needs a reason', 'without a reason: 422 "A reversal needs a reason"');
$since = last_activity_id();
[$c, $b] = act($bea, '/journal/reverse.php', ['entry' => $id, 'reason' => 'SMOKE wrong month']);
$rev = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $rev > 0 && $rev !== $id && ($b['location'] ?? '') === '/journal/' . $rev . '?notice=reversed' && str_starts_with((string) $b['did'], 'Reversed ' . $number . ' with JE-'), 'journal_entry_reverse: 200, the reversal\'s id, location the reversal');
$r = entry_json($bea, $rev);
ok($r['entry']['status'] === 'posted' && $r['entry']['source'] === 'reversal' && $r['entry']['entry_date'] === '2026-05-05' && $r['entry']['reversal_of']['journal_entry_id'] === $id && $r['entry']['lines'][0]['credit'] === '240.00' && $r['entry']['lines'][1]['debit'] === '240.00', 'the reversal: posted, source reversal, the original\'s date, lines swapped, linked to the original');
$o = entry_json($bea, $id);
ok($o['entry']['status'] === 'reversed' && $o['entry']['reversed_by']['journal_entry_id'] === $rev, 'the original: reversed, linked to the reversal');
$log = activity('journal_entry.reverse', $since);
$a = json_decode((string) $log[0]['after'], true);
ok(count($log) === 1 && (int) $log[0]['journal_entry_id'] === $id && $a['reversal_id'] === $rev && $a['reason'] === 'SMOKE wrong month' && $a['amount'] === '240.00', 'journal_entry.reverse on the original with reversal_id, reason, amount');
$body = page($bea, '/journal/' . $id)['body'];
ok(str_contains($body, 'id="entry-reversed-by-link"') && !str_contains($body, 'id="entry-reverse-btn"') && str_contains(page($bea, '/journal/' . $rev)['body'], 'id="entry-reverses-link"'), 'the pages link both ways; a reversed entry offers no Reverse');
[$c, $b] = act($bea, '/journal/reverse.php', ['entry' => $id, 'reason' => 'SMOKE again']);
ok($c === 422 && str_contains(msg($b), 'is reversed, not posted'), 'reversing a reversed entry: 422');
ok((float) balance_of('6100', '2026-05-31') == (float) balance_of('6100', '2026-05-04'), 'the books are back where they were (6100 unchanged by the pair)');
echo "2. Whose entry\n";
[$c, $b, $cid] = draft($carl, '2026-05-06', [['account' => '6100', 'debit' => '9'], ['account' => '1010', 'credit' => '9']], 'SMOKE Carl\'s');
act($carl, '/journal/post.php', ['entry' => $cid]);
[$c, $b] = act($bea, '/journal/reverse.php', ['entry' => $cid, 'reason' => 'SMOKE not mine']);
ok($c === 403 && msg($b) === 'You may not reverse, void or write off.', 'Bea on Carl\'s entry: 403 (journal.override)');
ok(str_contains(page($bea, '/journal/' . $cid)['body'], 'id="entry-reverse-not-yours"'), 'her page says only its author or an override reverses it');
[$c, $b] = act($carl, '/journal/reverse.php', ['entry' => $bea_posted = (function () use ($bea) { [$c, $b, $x] = draft($bea, '2026-05-07', [['account' => '6100', 'debit' => '3'], ['account' => '1010', 'credit' => '3']], 'SMOKE Bea\'s for Carl'); act($bea, '/journal/post.php', ['entry' => $x]); return $x; })(), 'reason' => 'SMOKE override']);
ok($c === 200, 'Carl (journal.override) reverses Bea\'s');
echo "3. The original's period closed → today\n";
[$c, $b, $mar] = draft($bea, '2026-03-10', [['account' => '6100', 'debit' => '12'], ['account' => '1010', 'credit' => '12']], 'SMOKE March to reverse later');
act($bea, '/journal/post.php', ['entry' => $mar]);
act($carl, '/periods/close.php', ['period' => period_id('2026-03')]);
$body = page($bea, '/journal/' . $mar)['body'];
ok(preg_match('/id="entry-reverse-date"[^>]*value="' . date('Y-m-d') . '"/', $body) === 1 && str_contains($body, 'its period is closed: today'), 'the form offers today when the original\'s period is closed');
[$c, $b] = act($bea, '/journal/reverse.php', ['entry' => $mar, 'reason' => 'SMOKE late', 'reverse_date' => '2026-03-15']);
ok($c === 422 && str_contains(msg($b), 'Period 2026-03 is closed'), 'a date in the closed period: the posting RAISE');
[$c, $b] = act($bea, '/journal/reverse.php', ['entry' => $mar, 'reason' => 'SMOKE late']);
$rev2 = (int) ($b['record_id'] ?? 0);
ok($c === 200 && (string) one('SELECT entry_date FROM journal_entries WHERE id = :i', ['i' => $rev2]) === date('Y-m-d'), 'with no date: the reversal lands today, in an open period');
act($carl, '/periods/reopen.php', ['period' => period_id('2026-03'), 'reason' => 'SMOKE restore']);
echo "4. A document-born entry\n";
q("INSERT INTO customers (name) VALUES ('SMOKE Docco') ON CONFLICT DO NOTHING");
$cust = (int) one("SELECT id FROM customers WHERE name = 'SMOKE Docco'");
$inv = (int) one("INSERT INTO invoices (customer_id, issue_date, due_date, currency) VALUES (:c, '2026-05-02', '2026-06-01', 'USD') RETURNING id", ['c' => $cust]);
$je = (int) one("INSERT INTO journal_entries (entry_date, memo, source, source_type, source_id, created_by) VALUES ('2026-05-02', 'SMOKE from invoice', 'invoice', 'invoice', :i, 1) RETURNING id", ['i' => $inv]);
q('INSERT INTO journal_lines (entry_id, line_no, account_id, debit, credit, customer_id) VALUES (:e, 1, :a, 100, 0, :c)', ['e' => $je, 'a' => account_id('1200'), 'c' => $cust]);
q('INSERT INTO journal_lines (entry_id, line_no, account_id, debit, credit) VALUES (:e, 2, :a, 0, 100)', ['e' => $je, 'a' => account_id('4000')]);
one('SELECT gl_entry_post(:e, 1)', ['e' => $je]);
[$c, $b] = act($carl, '/journal/reverse.php', ['entry' => $je, 'reason' => 'SMOKE from here']);
ok($c === 422 && msg($b) === 'Reverse it from the invoice (void it) so the document and the books agree.', 'a document-born entry (an invoice\'s, by SQL): 422 "Reverse it from the invoice …"');
$body = page($carl, '/journal/' . $je)['body'];
ok(str_contains($body, 'id="entry-reverse-from-document"') && str_contains($body, 'id="entry-source"') && str_contains($body, 'From invoice'), 'the page says so and names the source document');
echo "5. Void\n";
[$c, $b, $dr] = draft($bea, '2026-05-08', [['account' => '6100', 'debit' => '1']], 'SMOKE to void');
$since = last_activity_id();
[$c, $b] = act($bea, '/journal/void.php', ['entry' => $dr, 'reason' => 'SMOKE a mistake']);
ok($c === 200 && entry_status($dr) === 'void' && count(activity('journal_entry.void', $since)) === 1 && str_contains((string) activity('journal_entry.void', $since)[0]['after'], 'SMOKE a mistake'), 'a draft voided with a reason; journal_entry.void logged');
ok(str_contains(page($bea, '/journal/' . $dr)['body'], 'id="entry-head-status">void<') && !str_contains(page($bea, '/journal/' . $dr)['body'], 'id="entry-post-btn"'), 'the page: void, no actions');
[$c, $b] = act($bea, '/journal/void.php', ['entry' => $cid, 'reason' => 'SMOKE']);
ok($c === 422 && str_contains(msg($b), 'is posted and cannot be voided; reverse it instead'), 'voiding a posted entry: 422 "… reverse it instead"');
[$c, $b] = act($bea, '/journal/line-save.php', ['entry' => $dr, 'account' => '6100', 'debit' => '1']);
ok($c === 422 && str_contains(msg($b), 'it is void'), 'a line on a void entry: 422');
finish();
